"""Build results/v04/tables.md, results/v04/summary.json and results/v04/m1/proof_cost.png from the result files.
    python v04/report.py
Intervals: 95% percentile intervals from 2,000 resamples of policy families within seed, paired across arms."""
import glob, json, os, sys
import numpy as np
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
from stillway4.grader import grade

R = "results/v04"; out = []; SUM = {}
def P(*a): out.append(" ".join(str(x) for x in a))
def load(p): return json.load(open(p)) if os.path.exists(p) else None
def pct(x, d=1): return "–" if x is None else f"{100 * x:.{d}f}%"
def mean(xs): xs = [x for x in xs if x is not None]; return float(np.mean(xs)) if xs else None
RULES = [(th, w, st, cf) for th in (1, 2, 3) for w in (0, 1, 2) for st in (0, 1) for cf in (0, 1)]; FIELDS = ("kind", "slot", "jur", "lvl", "age", "tag", "evid", "pid", "ostat")
rng = np.random.default_rng(0)


def paired_ci(a_by_seed, b_by_seed):
    """a, b: per seed, dict family -> [successes, documents].  Difference a - b of pooled success, families resampled within seed."""
    diffs = []
    for _ in range(2000):
        na = da = nb = db = 0
        for fa, fb in zip(a_by_seed, b_by_seed):
            fams = sorted(set(fa) & set(fb)); pick = rng.integers(0, len(fams), len(fams))
            for i in pick: f = fams[i]; na += fa[f][0]; da += fa[f][1]; nb += fb[f][0]; db += fb[f][1]
        diffs.append(na / max(1, da) - nb / max(1, db))
    return [float(np.percentile(diffs, 2.5)), float(np.percentile(diffs, 97.5))]


P("# v0.4 result tables\n\nGenerated by `v04/report.py`. Final runs use the freeze-derived data salt 2701878737 and seeds 1 to 5 unless a row says pilot.\n")
