    for k, lab in (("swap_code", "Swap the selected code"), ("suppress", "Suppress it"), ("perturb_argument", "Change one argument")):
        P(f"| {lab} | {pct(mean([i[k]['outcome_changed_by_intervention'] for i in ivs]))} | {pct(mean([i[k]['learned_equals_macro_prediction'] for i in ivs]), 2)} | {', '.join(pct(i[k]['learned_equals_macro_prediction']) for i in ivs)} | {sum(i[k]['protected_statuses_changed'] for i in ivs)} of {sum(i[k]['protected_statuses'] for i in ivs)} |")
    P(f"\nWithout intervention the learned arm and the macro give identical documents in {pct(mean([i['no_intervention']['learned_equals_macro_documents'] for i in ivs]), 2)}. Compiled tables equal the network on {sum(i['compiled_tables_equal_network_documents'] for i in ivs)} of {sum(i['compiled_documents_checked'] for i in ivs)} documents.")
